/// Who holds the lock on a [`VtxoState::Locked`] VTXO.
///
/// Mirrors `bark::vtxo::VtxoLockHolder`. Action-based subsystems lock with
/// `Action`; pre-action subsystems (round, offboard, board, lightning
/// receive) lock with `Movement`. As upstream converts subsystems to
/// actions, new locks migrate from `Movement` to `Action` per-subsystem.
///
/// Serde tags match upstream's serialization: `"action"` / `"movement"`.
public enum VtxoLockHolder: Hashable, Equatable, Sendable {
    /// A wallet action checkpoint. `id` is upstream's `WalletActionId`
    /// (an opaque string).
    case action(id: String)
    /// A pre-action subsystem, keyed by its movement.
    case movement(id: UInt32)

    @inlinable static func decode(from reader: inout WireReader) -> VtxoLockHolder {
        let tag = reader.readU32()
        switch tag {
        case 0:
            return .action(id: reader.readString())
        case 1:
            return .movement(id: reader.readU32())
        default:
            fatalError("Invalid VtxoLockHolder tag: \(tag)")
        }
    }

    @inlinable func encode(to writer: inout WireWriter) {
        switch self {
        case let .action(id):
            writer.writeU32(0)
            writer.writeString(id)
        case let .movement(id):
            writer.writeU32(1)
            writer.writeU32(id)
        }
    }
}

/// Rich VTXO state, mirroring `bark::vtxo::VtxoState`.
///
/// Serde tags match upstream's kebab-case serialization:
/// `"spendable"` | `"locked"` | `"spent"` | `"exited"`.
public enum VtxoState: Hashable, Equatable, Sendable {
    /// Pure decode has no local wallet-state information.
    case unknown
    /// Available; can be spent in a future round.
    case spendable
    /// Locked by an operation. `holder` is `None` only for the narrow
    /// window between creating a fresh locked VTXO and pinning it to a
    /// specific operation, so a locked VTXO can legitimately carry no
    /// lock reason yet.
    case locked(holder: VtxoLockHolder?)
    /// Consumed.
    case spent
    /// In (or completed) a unilateral exit.
    case exited

    @inlinable static func decode(from reader: inout WireReader) -> VtxoState {
        let tag = reader.readU32()
        switch tag {
        case 0:
            return .unknown
        case 1:
            return .spendable
        case 2:
            return .locked(holder: reader.readOptional { reader in VtxoLockHolder.decode(from: &reader) })
        case 3:
            return .spent
        case 4:
            return .exited
        default:
            fatalError("Invalid VtxoState tag: \(tag)")
        }
    }

    @inlinable func encode(to writer: inout WireWriter) {
        switch self {
        case .unknown:
            writer.writeU32(0)
        case .spendable:
            writer.writeU32(1)
        case let .locked(holder):
            writer.writeU32(2)
            writer.writeOptional(holder) { writer, boltffiValue0 in boltffiValue0.encode(to: &writer) }
        case .spent:
            writer.writeU32(3)
        case .exited:
            writer.writeU32(4)
        }
    }
}

/// Terminal/in-flight state of an outgoing lightning send.
///
/// Mirrors `bark`'s `LightningSendState`. `pay_lightning_*` and
/// `check_lightning_payment` now return this so callers can drive the
/// crash-safe send flow themselves (initiate with `wait = false`, then poll).
public enum LightningSendStatus: Hashable, Equatable, Sendable {
    /// No record of this payment (never started, or already pruned).
    case unknown
    /// Send is in flight; HTLC VTXOs are locked.
    case inProgress(send: LightningSend)
    /// Send has settled; the preimage proves payment.
    case paid(paymentHash: String, preimage: String)

    @inlinable static func decode(from reader: inout WireReader) -> LightningSendStatus {
        let tag = reader.readU32()
        switch tag {
        case 0:
            return .unknown
        case 1:
            return .inProgress(send: LightningSend.decode(from: &reader))
        case 2:
            return .paid(paymentHash: reader.readString(), preimage: reader.readString())
        default:
            fatalError("Invalid LightningSendStatus tag: \(tag)")
        }
    }

    @inlinable func encode(to writer: inout WireWriter) {
        switch self {
        case .unknown:
            writer.writeU32(0)
        case let .inProgress(send):
            writer.writeU32(1)
            send.encode(to: &writer)
        case let .paid(paymentHash, preimage):
            writer.writeU32(2)
            writer.writeString(paymentHash)
            writer.writeString(preimage)
        }
    }
}

/// An onchain UTXO known to the wallet, mirroring `bark::onchain::Utxo`.
public enum OnchainUtxo: Hashable, Equatable, Sendable {
    /// A standard wallet UTXO.
    case local(outpoint: OutPoint, amountSats: UInt64, confirmationHeight: UInt32?)
    /// A spendable unilateral-exit output claimed from a VTXO.
    case exit(vtxoId: String, amountSats: UInt64, height: UInt32)

    @inlinable static func decode(from reader: inout WireReader) -> OnchainUtxo {
        let tag = reader.readU32()
