/// State of a unilateral exit, mirroring `bark::exit::ExitState`.
///
/// Serde tags match upstream's kebab-case serialization (`"start"`,
/// `"processing"`, `"awaiting-delta"`, `"claimable"`, `"claim-in-progress"`,
/// `"claimed"`, `"vtxo-already-spent"`, `"vtxo-swept"`, `"canceled"`), with camelCase fields.
public enum ExitState: Hashable, Equatable, Sendable {
    /// The exit was requested at the given tip.
    case start(tipHeight: UInt32)
    /// The exit transaction chain is being broadcast and confirmed.
    case processing(tipHeight: UInt32, transactions: [ExitTx])
    /// Fully confirmed; waiting out the exit delta until claimable.
    case awaitingDelta(tipHeight: UInt32, confirmedBlock: BlockRef, claimableHeight: UInt32)
    /// The exit output can be claimed.
    case claimable(tipHeight: UInt32, claimableSince: BlockRef, lastScannedBlock: BlockRef?)
    /// A claim transaction has been broadcast.
    case claimInProgress(tipHeight: UInt32, claimableSince: BlockRef, claimTxid: String)
    /// Terminal: the exit output was claimed (or spent deeper in the tree).
    case claimed(tipHeight: UInt32, txid: String, block: BlockRef)
    /// Terminal: the VTXO was already spent offchain, so the exit cannot
    /// proceed.
    case vtxoAlreadySpent(tipHeight: UInt32)
    /// Terminal: confirmed spends took inputs needed by the exit.
    case vtxoSwept(tipHeight: UInt32, spentInputs: [OutPoint])
    /// Resumable: the user canceled the exit before its final transaction
    /// was broadcast. The VTXO stays spendable.
    case canceled(tipHeight: UInt32)

    @inlinable static func decode(from reader: inout WireReader) -> ExitState {
        let tag = reader.readU32()
        switch tag {
        case 0:
            return .start(tipHeight: reader.readU32())
        case 1:
            return .processing(tipHeight: reader.readU32(), transactions: reader.readArray { reader in ExitTx.decode(from: &reader) })
        case 2:
            return .awaitingDelta(tipHeight: reader.readU32(), confirmedBlock: BlockRef.decode(from: &reader), claimableHeight: reader.readU32())
        case 3:
            return .claimable(tipHeight: reader.readU32(), claimableSince: BlockRef.decode(from: &reader), lastScannedBlock: reader.readOptional { reader in BlockRef.decode(from: &reader) })
        case 4:
            return .claimInProgress(tipHeight: reader.readU32(), claimableSince: BlockRef.decode(from: &reader), claimTxid: reader.readString())
        case 5:
            return .claimed(tipHeight: reader.readU32(), txid: reader.readString(), block: BlockRef.decode(from: &reader))
        case 6:
            return .vtxoAlreadySpent(tipHeight: reader.readU32())
        case 7:
            return .vtxoSwept(tipHeight: reader.readU32(), spentInputs: reader.readArray { reader in OutPoint.decode(from: &reader) })
        case 8:
            return .canceled(tipHeight: reader.readU32())
        default:
            fatalError("Invalid ExitState tag: \(tag)")
        }
    }

    @inlinable func encode(to writer: inout WireWriter) {
        switch self {
        case let .start(tipHeight):
            writer.writeU32(0)
            writer.writeU32(tipHeight)
        case let .processing(tipHeight, transactions):
            writer.writeU32(1)
            writer.writeU32(tipHeight)
            writer.writeArray(transactions) { writer, boltffiValue0 in boltffiValue0.encode(to: &writer) }
        case let .awaitingDelta(tipHeight, confirmedBlock, claimableHeight):
            writer.writeU32(2)
            writer.writeU32(tipHeight)
            confirmedBlock.encode(to: &writer)
            writer.writeU32(claimableHeight)
        case let .claimable(tipHeight, claimableSince, lastScannedBlock):
            writer.writeU32(3)
            writer.writeU32(tipHeight)
            claimableSince.encode(to: &writer)
            writer.writeOptional(lastScannedBlock) { writer, boltffiValue0 in boltffiValue0.encode(to: &writer) }
        case let .claimInProgress(tipHeight, claimableSince, claimTxid):
            writer.writeU32(4)
            writer.writeU32(tipHeight)
            claimableSince.encode(to: &writer)
            writer.writeString(claimTxid)
        case let .claimed(tipHeight, txid, block):
            writer.writeU32(5)
            writer.writeU32(tipHeight)
            writer.writeString(txid)
            block.encode(to: &writer)
        case let .vtxoAlreadySpent(tipHeight):
            writer.writeU32(6)
            writer.writeU32(tipHeight)
        case let .vtxoSwept(tipHeight, spentInputs):
            writer.writeU32(7)
            writer.writeU32(tipHeight)
            writer.writeArray(spentInputs) { writer, boltffiValue0 in boltffiValue0.encode(to: &writer) }
        case let .canceled(tipHeight):
            writer.writeU32(8)
            writer.writeU32(tipHeight)
        }
    }
}

